import { useState, useEffect } from 'react';

interface Todo {
  id: number;
  title: string;
  completed: boolean;
}

export default function TodoAutocomplete() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState<Todo | null>(null);

  useEffect(() => {
    const loadTodos = async () => {
      try {
        const res = await fetch('http://localhost:4000/api/todos');
        if (!res.ok) {
          throw new Error('Failed to fetch todos');
        }
        const data = (await res.json()) as Todo[];
        setTodos(data);
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Unknown error');
      } finally {
        setLoading(false);
      }
    };
    loadTodos();
  }, []);

  const trimmed = query.trim();
  const suggestions = trimmed
    ? todos.filter(todo =>
        todo.title.toLowerCase().includes(trimmed.toLowerCase())
      )
    : [];

  return (
    <div className="todo-autocomplete">
      <h1>Todo Autocomplete</h1>
      <input
        type="text"
        placeholder="Search todos..."
        value={query}
        onChange={e => setQuery(e.currentTarget.value)}
      />

      {loading && <div className="status">Loading suggestions...</div>}
      {error && (
        <div className="status error">Error: {error}</div>
      )}

      {!loading && !error && trimmed && (
        suggestions.length === 0 ? (
          <div className="status empty">No matches found.</div>
        ) : (
          <ul className="suggestions">
            {suggestions.map(todo => (
              <li
                key={todo.id}
                className="suggestion-item"
                onClick={() => {
                  setQuery(todo.title);
                  setSelected(todo);
                }}
              >
                {todo.title}
              </li>
            ))}
          </ul>
        )
      )}

      {selected && (
        <div className="selected">Selected: {selected.title}</div>
      )}
    </div>
  );
}
